% Punnett square: BbEe x BbEe (Labrador coat color, recessive epistasis at the E locus).
% Pitfall: do NOT use \draw grid -- dvisvgm misplaces grid lines; draw every line by hand.
% Pitfall: avoid unicode gender symbols in standalone; use dam/sire words.
\documentclass[tikz,border=10pt]{standalone}
\usetikzlibrary{calc}
\begin{document}
\definecolor{labblack}{HTML}{1A1A1A}
\definecolor{noseblack}{HTML}{4D4D4D}
\definecolor{labchoc}{HTML}{6B4226}
\definecolor{nosechoc}{HTML}{241610}
\definecolor{labyellow}{HTML}{E8C97A}
\definecolor{noseyellow}{HTML}{3E2A1E}

% doghead macro: real Noun Project icon paths traced by svg2tikz (see make_doghead_macro.py)
% macro: Labrador head traced from the Noun Project icon (omeneko) via svg2tikz.
% #1 = center coordinate, #2 = coat color, #3 = nose color.
% Original 5 paths: left ear, right ear, chin, nose, head (eyes are cutout subpaths).
\newcommand{\doghead}[3]{%
  % Path coordinates are ALREADY recentered on the head middle by make_doghead_macro.py,
  % so no extra shift is needed here. (A leftover duplicate shift caused misalignment.)
  \begin{scope}[shift={#1}, scale=0.52]
  \fill[#2]  (-0.5316, 0.7861).. controls (-1.1848, 0.8374) and (-1.4164, 0.0722) .. (-0.9639, -0.2848).. controls (-0.8941, -0.3398) and (-0.7932, -0.3294) .. (-0.7362, -0.2613).. controls (-0.3993, 0.1412) and (-0.8763, 0.4025) .. (-0.5316, 0.7861) -- cycle;
  \fill[#2]  (0.5317, 0.7861).. controls (1.1849, 0.8373) and (1.4164, 0.0721) .. (0.9639, -0.2849) -- (0.9639, -0.2848).. controls (0.8941, -0.3398) and (0.7933, -0.3293) .. (0.7362, -0.2612).. controls (0.3993, 0.1412) and (0.8764, 0.4025) .. (0.5317, 0.7861) -- cycle;
  \fill[#2]  (0.1848, -0.9370).. controls (0.0849, -1.0385) and (-0.0848, -1.0385) .. (-0.1847, -0.9370) -- (-0.1848, -0.9370).. controls (-0.1136, -0.9254) and (-0.0485, -0.8901) .. (0.0000, -0.8367).. controls (0.0485, -0.8900) and (0.1136, -0.9254) .. (0.1848, -0.9370) -- cycle;
  \fill[#3]  (0.1736, -0.4402).. controls (0.1803, -0.4219) and (0.1786, -0.4017) .. (0.1693, -0.3847) -- (0.1694, -0.3847).. controls (0.1602, -0.3672) and (0.1442, -0.3545) .. (0.1251, -0.3495).. controls (0.0436, -0.3282) and (-0.0419, -0.3281) .. (-0.1233, -0.3491).. controls (-0.1630, -0.3592) and (-0.1876, -0.4008) .. (-0.1737, -0.4402).. controls (-0.1456, -0.5200) and (-0.0932, -0.5800) .. (-0.0264, -0.6092) -- (-0.0262, -0.6094).. controls (-0.0095, -0.6167) and (0.0095, -0.6167) .. (0.0263, -0.6094).. controls (0.0930, -0.5800) and (0.1455, -0.5200) .. (0.1736, -0.4402) -- cycle;
  \fill[#2]  (0.4703, 0.7309).. controls (0.4433, 0.7609) and (0.4419, 0.8060) .. (0.4670, 0.8376).. controls (0.3491, 0.9191) and (0.1936, 0.9672) .. (0.0000, 0.9672).. controls (-0.1936, 0.9672) and (-0.3491, 0.9190) .. (-0.4669, 0.8375) -- (-0.4669, 0.8376).. controls (-0.4418, 0.8060) and (-0.4431, 0.7609) .. (-0.4701, 0.7309).. controls (-0.7632, 0.4047) and (-0.3510, 0.1630) .. (-0.6206, -0.2447).. controls (-0.5573, -0.3702) and (-0.5581, -0.3824) .. (-0.5272, -0.5641).. controls (-0.4652, -0.9294) and (-0.0939, -0.9322) .. (-0.0110, -0.6970).. controls (-0.0858, -0.6914) and (-0.2006, -0.6123) .. (-0.2516, -0.4677).. controls (-0.2814, -0.3834) and (-0.2310, -0.2912) .. (-0.1437, -0.2690) -- (-0.1436, -0.2690).. controls (-0.0488, -0.2449) and (0.0508, -0.2450) .. (0.1458, -0.2695).. controls (0.1870, -0.2803) and (0.2219, -0.3078) .. (0.2420, -0.3455).. controls (0.2621, -0.3831) and (0.2657, -0.4274) .. (0.2516, -0.4677).. controls (0.2008, -0.6118) and (0.0862, -0.6914) .. (0.0110, -0.6970).. controls (0.0940, -0.9324) and (0.4651, -0.9295) .. (0.5271, -0.5641).. controls (0.5586, -0.3792) and (0.5582, -0.3698) .. (0.6206, -0.2446).. controls (0.3521, 0.1615) and (0.7615, 0.4066) .. (0.4703, 0.7309) -- cycle(-0.2325, 0.0725).. controls (-0.2325, 0.0177) and (-0.3152, 0.0177) .. (-0.3152, 0.0725) -- (-0.3152, 0.1579).. controls (-0.3152, 0.2127) and (-0.2325, 0.2127) .. (-0.2325, 0.1579) -- cycle(0.3157, 0.0725).. controls (0.3157, 0.0177) and (0.2330, 0.0177) .. (0.2330, 0.0725) -- (0.2330, 0.1579).. controls (0.2330, 0.2127) and (0.3157, 0.2127) .. (0.3157, 0.1579) -- cycle;
  \end{scope}
}

\begin{tikzpicture}[cellw/.store in=\cellw, cellw=4.2,
                    cellh/.store in=\cellh, cellh=1.5]

% ---- gamete headers (products of meiosis); no frames, no corner label ----

\node[font=\large\bfseries] at (3.50,0.45) {BE};
\node[font=\large\bfseries] at (7.70,0.45) {Be};
\node[font=\large\bfseries] at (11.90,0.45) {bE};
\node[font=\large\bfseries] at (16.10,0.45) {be};
\node[anchor=west, font=\large\bfseries] at (0.35,-0.75) {BE};
\node[anchor=west, font=\large\bfseries] at (0.35,-2.25) {Be};
\node[anchor=west, font=\large\bfseries] at (0.35,-3.75) {bE};
\node[anchor=west, font=\large\bfseries] at (0.35,-5.25) {be};

% ---- 16 offspring cells ----

% BE x BE -> BBEE
\node[text=black, font=\ttfamily\bfseries] at (2.70,-0.75) {BBEE};
\doghead{(4.43,-0.75)}{labblack}{noseblack}

% BE x Be -> BBEe
\node[text=black, font=\ttfamily\bfseries] at (6.90,-0.75) {BBEe};
\doghead{(8.63,-0.75)}{labblack}{noseblack}

% BE x bE -> BbEE
\node[text=black, font=\ttfamily\bfseries] at (11.10,-0.75) {BbEE};
\doghead{(12.83,-0.75)}{labblack}{noseblack}

% BE x be -> BbEe
\node[text=black, font=\ttfamily\bfseries] at (15.30,-0.75) {BbEe};
\doghead{(17.03,-0.75)}{labblack}{noseblack}

% Be x BE -> BBEe
\node[text=black, font=\ttfamily\bfseries] at (2.70,-2.25) {BBEe};
\doghead{(4.43,-2.25)}{labblack}{noseblack}

% Be x Be -> BBee
\node[text=black, font=\ttfamily\bfseries] at (6.90,-2.25) {BBee};
\doghead{(8.63,-2.25)}{labyellow}{noseyellow}

% Be x bE -> BbEe
\node[text=black, font=\ttfamily\bfseries] at (11.10,-2.25) {BbEe};
\doghead{(12.83,-2.25)}{labblack}{noseblack}

% Be x be -> Bbee
\node[text=black, font=\ttfamily\bfseries] at (15.30,-2.25) {Bbee};
\doghead{(17.03,-2.25)}{labyellow}{noseyellow}

% bE x BE -> BbEE
\node[text=black, font=\ttfamily\bfseries] at (2.70,-3.75) {BbEE};
\doghead{(4.43,-3.75)}{labblack}{noseblack}

% bE x Be -> BbEe
\node[text=black, font=\ttfamily\bfseries] at (6.90,-3.75) {BbEe};
\doghead{(8.63,-3.75)}{labblack}{noseblack}

% bE x bE -> bbEE
\node[text=black, font=\ttfamily\bfseries] at (11.10,-3.75) {bbEE};
\doghead{(12.83,-3.75)}{labchoc}{nosechoc}

% bE x be -> bbEe
\node[text=black, font=\ttfamily\bfseries] at (15.30,-3.75) {bbEe};
\doghead{(17.03,-3.75)}{labchoc}{nosechoc}

% be x BE -> BbEe
\node[text=black, font=\ttfamily\bfseries] at (2.70,-5.25) {BbEe};
\doghead{(4.43,-5.25)}{labblack}{noseblack}

% be x Be -> Bbee
\node[text=black, font=\ttfamily\bfseries] at (6.90,-5.25) {Bbee};
\doghead{(8.63,-5.25)}{labyellow}{noseyellow}

% be x bE -> bbEe
\node[text=black, font=\ttfamily\bfseries] at (11.10,-5.25) {bbEe};
\doghead{(12.83,-5.25)}{labchoc}{nosechoc}

% be x be -> bbee
\node[text=black, font=\ttfamily\bfseries] at (15.30,-5.25) {bbee};
\doghead{(17.03,-5.25)}{labyellow}{noseyellow}


% ---- table lines ----
\draw (1.4,0) rectangle (1.4+16.8,-6.0);

\draw (5.60,0) -- (5.60,-6.0);
\draw (9.80,0) -- (9.80,-6.0);
\draw (14.00,0) -- (14.00,-6.0);
\draw (1.4,-1.50) -- (18.2,-1.50);
\draw (1.4,-3.00) -- (18.2,-3.00);
\draw (1.4,-4.50) -- (18.2,-4.50);

% attribution required by the Noun Project license (CC BY); keep visible
\node[anchor=north east, font=\scriptsize, text=black!50] at (18.2,-6.3)
    {Labrador icon: Created by omeneko, from the Noun Project};

\end{tikzpicture}
\end{document}
